/**
 * THE PARITY PROOF for key letters (`docs/security/private-repos.md` §20, §22.3): every
 * `key_letter__*` vector in `forge-contracts/vectors/` (generated by
 * `tools/private-repos-vectors/key_letters.py` and, for the `read*` ops, `access.py`), run against
 * `./key-letter`, `./read-letter` and `./doc`'s shared-key helpers. forge-core
 * `private::key_letter::conformance` and `private::access_conformance` run the same files with the
 * same input and output shapes.
 */

import { readFileSync, readdirSync } from 'node:fs'
import { resolve } from 'node:path'
import { describe, expect, it } from 'vitest'

import { bytesToHex, hexToBytes, sha256 } from './bytes'
import {
  KeyLetterError,
  branchLetterFromTyped,
  branchLetterToTyped,
  decodeKeyLetter,
  encodeKeyLetter,
  openKeyLetter,
  type BranchLetter,
  type JsonValue,
  type TypedLetter,
} from "./key-letter";
import { EpochKeys } from "./keys";
import { PackError, openPackWithFileKey, parseHeader } from "./pack";
import {
  membersObjKey,
  openSharedWithKey,
  readObjKey,
  type OpenResult,
  type PrivateDoc,
} from "./doc";
import {
  readLetterFromTyped,
  readLetterToTyped,
  type ReadLetter,
  type ReadTarget,
} from "./read-letter";
import type { PrivateDocType } from "./tlv";
import { sealLetterArtifactWith } from "./testing";

type Json = null | boolean | number | string | Json[] | { [k: string]: Json }
type Obj = { readonly [k: string]: Json }

interface Vector {
  readonly name: string
  readonly input: Obj
  readonly expected: Json
}

const VECTORS_DIR = resolve(process.cwd(), '..', 'forge-contracts', 'vectors')
const FILES = readdirSync(VECTORS_DIR)
  .filter((f) => f.startsWith('key_letter__') && f.endsWith('.json'))
  .sort()

const str = (j: Json | undefined): string => j as string
const obj = (j: Json | undefined): Obj => j as Obj
const arr = (j: Json | undefined): Json[] => j as Json[]
const hex = (j: Json | undefined): Uint8Array => hexToBytes(str(j))

function typed(j: Json | undefined): TypedLetter {
  const o = obj(j)
  return {
    type: str(o.type),
    v: o.v as number,
    fields: obj(o.fields) as { [k: string]: JsonValue },
  }
}

const typedJson = (t: TypedLetter): Json => ({
  type: t.type,
  v: t.v,
  fields: t.fields as Json,
})

function branchJson(b: BranchLetter): Json {
  return {
    name: b.name,
    refNameHash: bytesToHex(b.refNameHash),
    head: {
      blind: bytesToHex(b.head.blind),
      oid: bytesToHex(b.head.oid),
      salt: bytesToHex(b.head.salt),
    },
    packs: b.packs.map((p) => ({
      packHash: bytesToHex(p.packHash),
      key: bytesToHex(p.key),
    })),
    asOf: b.asOf,
  }
}

function branchOf(j: Json | undefined): BranchLetter {
  const o = obj(j)
  const h = obj(o.head)
  return {
    name: str(o.name),
    refNameHash: hex(o.refNameHash),
    head: { blind: hex(h.blind), oid: hex(h.oid), salt: hex(h.salt) },
    packs: arr(o.packs).map((p) => ({
      packHash: hex(obj(p).packHash),
      key: hex(obj(p).key),
    })),
    asOf: o.asOf as number,
  }
}

async function runFormat(i: Obj): Promise<Json> {
  let letter: TypedLetter
  if (i.branch !== undefined) {
    const t = await branchLetterToTyped(branchOf(i.branch))
    if (t === null) throw new Error('a well-formed branch letter')
    expect(branchJson((await branchLetterFromTyped(t)) as BranchLetter)).toEqual(i.branch)
    letter = t
  } else {
    letter = typed(i.letter)
  }
  try {
    const pt = encodeKeyLetter(letter)
    expect(decodeKeyLetter(pt)).toEqual(letter)
    return { letter: typedJson(letter), plaintextHex: bytesToHex(pt) }
  } catch (e) {
    if (e instanceof KeyLetterError) return { error: e.code }
    throw e
  }
}

async function runDecode(i: Obj): Promise<Json> {
  const results: Json[] = []
  for (const c of arr(i.cases)) {
    const name = str(obj(c).name)
    const t = decodeKeyLetter(hex(obj(c).plaintextHex))
    if (t === null) {
      results.push({ name, error: 'malformed' })
      continue
    }
    const b = await branchLetterFromTyped(t)
    results.push({
      name,
      letter: typedJson(t),
      branch: b === null ? null : branchJson(b),
    })
  }
  return { results }
}

async function runSeal(i: Obj): Promise<Json> {
  const plain = encodeKeyLetter(typed(i.letter))
  const sealed = await sealLetterArtifactWith(
    hex(i.repoId),
    hex(obj(i.sender).priv),
    i.senderKeyId as number,
    hex(i.ownerId),
    arr(i.recipients).map((r) => ({
      identityId: hex(obj(r).identityId),
      publicKey: hex(obj(r).publicKey),
    })),
    plain,
    hex(i.kObj),
    hex(i.fileId),
    arr(i.ivs).map(hex),
  )
  return {
    sealedHex: bytesToHex(sealed),
    packHash: bytesToHex(await sha256(sealed)),
    sizeBytes: sealed.length,
  }
}

async function runOpen(i: Obj): Promise<Json> {
  const m = obj(i.manifest)
  const ownerKeys = arr(i.ownerKeys).map((k) => ({
    id: obj(k).id as number,
    purpose: obj(k).purpose as number,
    keyType: obj(k).keyType as number,
    data: hex(obj(k).data),
  }))
  const results: Json[] = []
  for (const r of arr(i.readers)) {
    const reader = {
      identityId: hex(obj(r).identityId),
      secrets: arr(obj(r).keys).map(hex),
    }
    const got = await openKeyLetter(
      hex(i.repoId),
      { packHash: hex(m.packHash), sizeBytes: m.sizeBytes as number },
      hex(i.sealedHex),
      ownerKeys,
      reader,
    )
    results.push('error' in got ? { error: got.error } : { letter: typedJson(got.letter), recipients: got.recipients })
  }
  return { results }
}

async function runFileKey(i: Obj): Promise<Json> {
  const sealed = hex(i.sealedHex)
  const keys = await EpochKeys.import(hex(i.repoId), i.epoch as number, hex(i.epochKey))
  const header = parseHeader(sealed)
  const key = await keys.rawPackKey(header.fileId)
  const plain = await openPackWithFileKey(sealed, sealed.length, key)
  let wrong = 'opened'
  try {
    await openPackWithFileKey(sealed, sealed.length, hex(i.wrongKey))
  } catch (e) {
    if (e instanceof PackError) wrong = e.code
    else throw e
  }
  return {
    fileKey: bytesToHex(key),
    plaintextSha256: bytesToHex(await sha256(plain)),
    plaintextLen: plain.length,
    wrongKey: wrong,
  }
}

// --- the `read` ops (forge-core `access_conformance::run_read`) ----------------------------------

function targetJson(t: ReadTarget): Json {
  if ("branch" in t) return { branch: bytesToHex(t.branch) };
  return "pr" in t ? { pr: t.pr } : { issue: t.issue };
}

function readJson(r: ReadLetter): Json {
  return {
    job: bytesToHex(r.job),
    asOf: r.asOf,
    target: targetJson(r.target),
    docs: r.docs.map((d) => ({
      id: bytesToHex(d.id),
      revision: d.revision,
      key: bytesToHex(d.key),
    })),
    packs: r.packs.map((p) => ({
      packHash: bytesToHex(p.packHash),
      key: bytesToHex(p.key),
    })),
    heads: r.heads.map((h) => ({
      blind: bytesToHex(h.blind),
      oid: bytesToHex(h.oid),
      salt: bytesToHex(h.salt),
    })),
  };
}

function readOf(j: Json | undefined): ReadLetter {
  const o = obj(j);
  const t = obj(o.target);
  const k = Object.keys(t)[0] as string;
  const target: ReadTarget =
    k === "pr"
      ? { pr: t.pr as number }
      : k === "issue"
        ? { issue: t.issue as number }
        : { branch: hex(t.branch) };
  return {
    job: hex(o.job),
    asOf: o.asOf as number,
    target,
    docs: arr(o.docs).map((d) => ({
      id: hex(obj(d).id),
      revision: obj(d).revision as number,
      key: hex(obj(d).key),
    })),
    packs: arr(o.packs).map((p) => ({
      packHash: hex(obj(p).packHash),
      key: hex(obj(p).key),
    })),
    heads: arr(o.heads).map((h) => ({
      blind: hex(obj(h).blind),
      oid: hex(obj(h).oid),
      salt: hex(obj(h).salt),
    })),
  };
}

async function runReadFormat(i: Obj): Promise<Json> {
  const t = await readLetterToTyped(readOf(i.read));
  if (t === null) throw new Error("a well-formed read letter");
  expect(readJson((await readLetterFromTyped(t)) as ReadLetter)).toEqual(
    i.read,
  );
  const pt = encodeKeyLetter(t);
  expect(decodeKeyLetter(pt)).toEqual(t);
  return { letter: typedJson(t), plaintextHex: bytesToHex(pt) };
}

async function runReadDecode(i: Obj): Promise<Json> {
  const results: Json[] = [];
  for (const c of arr(i.cases)) {
    const name = str(obj(c).name);
    const t = decodeKeyLetter(hex(obj(c).plaintextHex));
    if (t === null) {
      results.push({ name, error: "malformed" });
      continue;
    }
    const r = await readLetterFromTyped(t);
    results.push({
      name,
      letter: typedJson(t),
      read: r === null ? null : readJson(r),
    });
  }
  return { results };
}

function headerDoc(j: Json | undefined): PrivateDoc {
  const h = obj(j);
  const opt = (k: string): Uint8Array | undefined =>
    h[k] === undefined || h[k] === null ? undefined : hex(h[k]);
  return {
    type: str(h.type) as PrivateDocType,
    ...(h.vis !== undefined ? { vis: h.vis as "public" | "private" } : {}),
    ownerId: hex(h.ownerId),
    epoch: h.epoch as number,
    ...(h.number !== undefined ? { number: h.number as number } : {}),
    ...(opt("targetId") ? { targetId: opt("targetId") } : {}),
    ...(opt("patchId") ? { patchId: opt("patchId") } : {}),
    ...(opt("baseRefNameHash")
      ? { baseRefNameHash: opt("baseRefNameHash") }
      : {}),
    ...(opt("sourceRefNameHash")
      ? { sourceRefNameHash: opt("sourceRefNameHash") }
      : {}),
  };
}

function openedJson(r: OpenResult): Json {
  if (r.status === "readable") {
    // bytes (a members-only PR's real head and its salt) as lowercase hex, as forge-core writes them
    const fields = Object.fromEntries(
      Object.entries(r.fields).map(([k, v]) => [k, v instanceof Uint8Array ? bytesToHex(v) : v]),
    );
    return { status: "readable", fields: fields as unknown as Json };
  }
  return r.status === "unreadable"
    ? { status: "unreadable", reason: r.reason }
    : { status: "malformed" };
}

async function runReadOpenDoc(i: Obj): Promise<Json> {
  const repoId = hex(i.repoId);
  const keys = await EpochKeys.import(repoId, i.epoch as number, hex(i.epochKey));
  let wrong: Json = null;
  const results: Json[] = [];
  for (const d of arr(i.docs)) {
    const doc = headerDoc(obj(d).header);
    const enc = hex(obj(d).encHex);
    const key = await readObjKey(keys, doc, enc);
    if (key === null) throw new Error("a members-only revision the epoch key opens");
    if (obj(d).name === "comment") {
      // a bundle's key for the same comment is the same key
      expect(await membersObjKey(keys, doc, enc)).toEqual(key);
      wrong = openedJson(await openSharedWithKey(repoId, doc, enc, hex(i.wrongKey)));
    } else if (doc.type === "event") {
      // a bundle does not publish an event
      expect(await membersObjKey(keys, doc, enc)).toBeNull();
    }
    results.push({
      name: obj(d).name as Json,
      objKey: bytesToHex(key),
      opened: openedJson(await openSharedWithKey(repoId, doc, enc, key)),
    });
  }
  return { results, wrongKey: wrong };
}

describe("key letter conformance vectors", () => {
  it("finds them", () => {
    expect(FILES.length).toBeGreaterThanOrEqual(15);
  });
  for (const f of FILES) {
    const v = JSON.parse(readFileSync(resolve(VECTORS_DIR, f), 'utf8')) as Vector
    it(v.name, async () => {
      const i = v.input
      const run = {
        format: runFormat,
        decode: runDecode,
        seal: runSeal,
        open: runOpen,
        fileKey: runFileKey,
        readFormat: runReadFormat,
        readDecode: runReadDecode,
        readOpenDoc: runReadOpenDoc,
      }[str(i.op)];
      if (run === undefined) throw new Error(`unknown op ${str(i.op)}`);
      expect(await run(i)).toEqual(v.expected);
    });
  }
  it('refuses a letter past the cap', () => {
    expect(() =>
      encodeKeyLetter({
        type: 'branch',
        v: 1,
        fields: { x: 'a'.repeat(64 * 1024) },
      }),
    ).toThrow(KeyLetterError)
  })
})
